@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (isLoading)
{
    <p>Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="GetFilteredTasks("To Do")"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveTask="HandleMoveTask"
                     OnAddTask="HandleAddTask" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="GetFilteredTasks("In Progress")"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveTask="HandleMoveTask"
                     OnAddTask="HandleAddTask" />

        <BoardColumn ColumnName="Done"
                     Tasks="GetFilteredTasks("Done")"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveTask="HandleMoveTask"
                     OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> tasks = [];
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private IReadOnlyList<TaskItem> GetFilteredTasks(string status)
    {
        IEnumerable<TaskItem> filtered = tasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }

        return filtered.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveTask((TaskItem Task, string Direction) args)
    {
        var currentIndex = Array.IndexOf(Columns, args.Task.Status);
        var newIndex = args.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= Columns.Length)
            return;

        var newStatus = Columns[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(args.Task.Id, newStatus);
            var index = tasks.FindIndex(t => t.Id == args.Task.Id);
            if (index >= 0)
            {
                tasks[index] = args.Task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate, string Status) args)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            tasks.Add(newTask);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 0.5rem 1rem;
    min-width: 80px;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.4rem;
    font-weight: 700;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search bar */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.95rem;
}

/* Column layout */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 6px;
    padding: 0.75rem;
    min-width: 0;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.column-count {
    background: #dee2e6;
    border-radius: 10px;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

/* Task card */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    padding: 0.6rem;
}

.task-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.4rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.4rem;
    border-radius: 3px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-details {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.4rem;
}

.task-actions {
    display: flex;
    gap: 0.25rem;
}

.btn-move {
    flex: 1;
    padding: 0.25rem 0.4rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 3px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-move:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Add task form */
.btn-add-task {
    width: 100%;
    padding: 0.4rem;
    margin-top: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 4px;
    background: transparent;
    color: #6c757d;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin-top: 0.5rem;
    padding: 0.6rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 4px;
}

.add-task-form input,
.add-task-form select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 3px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save {
    flex: 1;
    padding: 0.35rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 3px;
    cursor: pointer;
}

.btn-save:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-cancel {
    flex: 1;
    padding: 0.35rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 3px;
    cursor: pointer;
}

.btn-cancel:hover:not(:disabled) {
    background: #5c636a;
}

.form-error {
    color: #dc3545;
    font-size: 0.8rem;
    margin: 0;
}

/* Error state */
.board-error {
    padding: 1rem;
    background: #f8d7da;
    border-radius: 6px;
    color: #842029;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.35rem 1rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 3px;
    cursor: pointer;
}

